script:
const searchType = bh.input.query?.searchType;
const searchValue = bh.input.query?.searchValue;

bh.local.sqlParams = [];

if (!searchType && !searchValue) {

    bh.local.sql = `
        SELECT 
            id,
            policy_number,
            customer_id,
            policy_status,
            policy_start_date,
            policy_end_date,
            insured_name,
            vehicle_registration,
            vehicle_make,
            vehicle_model,
            vehicle_year,
            coverage_type,
            covered_perils,
            excess_amount,
            sum_insured,
            currency
        FROM policy_master
        ORDER BY id
    `;

}
else if (searchType && searchValue) {

    const columnMap = {
        POLICY_NUMBER: "policy_number",
        REGISTRATION_NUMBER: "vehicle_registration",
        CUSTOMER_ID: "customer_id"
    };

    const column = columnMap[searchType];

    if (!column) {
        throw new Error(
            "Invalid searchType. Use POLICY_NUMBER, REGISTRATION_NUMBER, or CUSTOMER_ID."
        );
    }

    bh.local.sql = `
        SELECT 
            id,
            policy_number,
            customer_id,
            policy_status,
            policy_start_date,
            policy_end_date,
            insured_name,
            vehicle_registration,
            vehicle_make,
            vehicle_model,
            vehicle_year,
            coverage_type,
            covered_perils,
            excess_amount,
            sum_insured,
            currency
        FROM policy_master
        WHERE ${column} = $1
        ORDER BY id
    `;

    bh.local.sqlParams = [searchValue];

}
else {

    throw new Error(
        "searchType and searchValue must be provided together."
    );
}
